var e=[{title:`Ustaw skakankę`,text:`Wybierz skakankę, która obraca się płynnie, nie zahaczając o stopy. Typowy pierwszy dobór to stanięcie w pobliżu jej środka i uniesienie uchwytów w stronę dolnej części klatki piersiowej lub pach, a potem dostosowanie do grubości liny i Twoich umiejętności. Upewnij się, że masz dużo miejsca nad głową, po bokach i na podłodze, zanim zaczniesz skakać.`},{title:`Naucz się małego podstawowego skoku`,text:`Trzymaj łokcie wygodnie blisko żeber i obracaj linę głównie nadgarstkami, bez wymachiwania całymi ramionami. Używaj krótkich, rozluźnionych skoków na tyle wysokich, by przejść nad liną, bez wysokiego podciągania kolan. Ląduj miękko, pozwalając kostkom i kolanom się uginać; nie próbuj trzymać nóg całkowicie sztywno.`},{title:`Dodawaj warianty stopniowo`,text:`Zacznij od pojedynczych obrotów, nawet jeśli udają się tylko dwa lub trzy, zanim trzeba zaczynać od nowa. Przejdź do krótkich ciągłych serii, a potem dodaj naprzemienne stopy, krok bokserski lub przesunięcia na boki, gdy poprawi się Twój rytm. Sztuczki takie jak double-under przychodzą po niezawodnym podstawowym rytmie.`},{title:`Unikaj zbyt dużego uderzenia i frustracji`,text:`Wielokrotne skakanie obciąża łydki i ścięgna Achillesa, więc duże nagłe zwiększenia mogą sprawić, że będą bolały. Jeśli lina ciągle się zahacza, może być za długa, za krótka lub źle zgrana w czasie; nie oznacza to, że nie jesteś sprawny. Noś buty i używaj powierzchni z dobrą przyczepnością oraz unikaj śliskich płytek i zatłoczonych pomieszczeń.`},{title:`Korzystanie z TrainUp`,text:`Plan zawiera skakankę tylko wtedy, gdy pozwalają na to Twój sprzęt oraz ustawienia Profilu dotyczące wysokości sufitu, podłoża, skakania i hałasu. Na początku utrzymuj krótkie interwały. Jeśli powstrzymują Cię umiejętności lub uderzenie, trening podtrzymają boks z cieniem lub marsz w miejscu.`}];var o=[{label:`CDC: pomiar intensywności wysiłku i test mowy`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`Biblioteka ćwiczeń ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`CDC: zalecenia dotyczące aktywności fizycznej dorosłych`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var t={sections:e,sources:o};export{t as default,e as sections,o as sources};